description:
Write lesson 3.03's anchor layout and the splitter's clamp:

```cpp
struct RECT { long left, top, right, bottom; };
struct Anchors { bool left, top, right, bottom; };

RECT anchorLayout(RECT design, Anchors a, int designW, int designH, int newW, int newH);
int clampSplit(int pos, int total, int minLeft, int minRight, int bar);
```

**anchorLayout**: `design` is where the control was in a client area of `designW × designH`. For each axis, with `d` the change of the client size on that axis:
- both edges anchored: the far edge moves by `d` (the control stretches);
- only the near edge (left or top): nothing changes;
- only the far edge (right or bottom): both edges move by `d`;
- neither: the size stays, and the centre is placed at the same **fraction** of the new size (computed in doubles and rounded to the nearest whole pixel, halves away from zero; the near edge is that centre minus half the size, rounded down).

**clampSplit**: the splitter bar starts at `pos` and is `bar` pixels wide inside `total`. The left pane is `0 .. pos` and the right pane `pos + bar .. total`. Clamp `pos` so the left pane is at least `minLeft` and the right pane at least `minRight`; if both cannot fit, the left pane wins (`pos = minLeft`).

starter.solution.cpp:
struct RECT { long left, top, right, bottom; };
struct Anchors { bool left, top, right, bottom; };

RECT anchorLayout(RECT design, Anchors a, int designW, int designH, int newW, int newH) { return design; }
int clampSplit(int pos, int total, int minLeft, int minRight, int bar) { return pos; }

solution.solution.cpp:
#include <algorithm>
#include <cmath>

struct RECT { long left, top, right, bottom; };
struct Anchors { bool left, top, right, bottom; };

namespace
{
    void axis(long& lo, long& hi, bool nearAnchor, bool farAnchor, int oldSize, int newSize)
    {
        const long d{ newSize - oldSize };
        if (nearAnchor && farAnchor) { hi += d; return; }
        if (nearAnchor) return;
        if (farAnchor) { lo += d; hi += d; return; }
        const long size{ hi - lo };
        const double fraction{ (lo + hi) / 2.0 / oldSize };
        const long centre{ static_cast<long>(std::lround(fraction * newSize)) };
        lo = centre - static_cast<long>(std::floor(size / 2.0));
        hi = lo + size;
    }
}

RECT anchorLayout(RECT design, Anchors a, int designW, int designH, int newW, int newH)
{
    RECT r{ design };
    axis(r.left, r.right, a.left, a.right, designW, newW);
    axis(r.top, r.bottom, a.top, a.bottom, designH, newH);
    return r;
}

int clampSplit(int pos, int total, int minLeft, int minRight, int bar)
{
    pos = std::min(pos, total - bar - minRight);
    return std::max(pos, minLeft);
}

unitTests:
bool same(RECT r, long l, long t, long rr, long b) { return r.left == l && r.top == t && r.right == rr && r.bottom == b; }
const RECT list{ 10, 40, 390, 250 }, ok{ 220, 260, 300, 286 }, search{ 10, 10, 390, 34 }, logo{ 150, 100, 250, 140 };
TEST("stretching") { CHECK(same(anchorLayout(list, { true, true, true, true }, 400, 300, 600, 500), 10, 40, 590, 450)); CHECK(same(anchorLayout(search, { true, true, true, false }, 400, 300, 600, 500), 10, 10, 590, 34)); }
TEST("following the far edge") { CHECK(same(anchorLayout(ok, { false, false, true, true }, 400, 300, 600, 500), 420, 460, 500, 486)); CHECK(same(anchorLayout(ok, { false, false, true, true }, 400, 300, 300, 200), 120, 160, 200, 186)); }
TEST("staying put") { CHECK(same(anchorLayout(ok, { true, true, false, false }, 400, 300, 999, 999), 220, 260, 300, 286)); }
TEST("centred") { CHECK(same(anchorLayout(logo, { false, false, false, false }, 400, 300, 600, 500), 250, 180, 350, 220)); CHECK(same(anchorLayout({ 0, 0, 11, 10 }, { false, true, false, true }, 100, 100, 201, 100), 6, 0, 17, 10)); }
TEST("splitter") {
    CHECK_EQ(clampSplit(300, 800, 100, 150, 6), 300); CHECK_EQ(clampSplit(50, 800, 100, 150, 6), 100); CHECK_EQ(clampSplit(700, 800, 100, 150, 6), 644);
    CHECK_EQ(clampSplit(120, 200, 100, 150, 6), 100);
}

